					try (LmdbNativeFactorCursor fresh = fixture.leaf().openFactors(fixture.row)) {
						assertTrue(fresh.next());
						assertNotEquals(generation, raw.generation(), "the next actual chunk reuses/resets the raw batch");
						assertThrows(IllegalStateException.class, stale::next, "stale traversal is rejected even if a decode window had buffered values");
						FactorEnvironment factors = fresh.factors(); assertSame(raw.source(), factors.batch(a).source());
						stale.bind(factors.batch(a), factors.lane(a));
						Value root = fixture.source.lazyValue(fixture.row.slots[0], ValuePosition.SUBJECT);
						assertEquals(fixture.memoryValues(root, a), decodedValues(stale, fixture.source));
						assertThrows(IllegalStateException.class, abandonedView::next, "the retained product rejects the old environment epoch");
					}
