	@ParameterizedTest(name = "bodyFailure={0}")
	@ValueSource(booleans = { false, true })
	void opaqueCallbackCleanupPreservesPrimaryAndExternalSourceOwnership(boolean bodyFailure, TestReporter reporter)
			throws Exception {
		try (OwnedFixture fixture = new OwnedFixture(directory, 4, false)) {
			RuntimeException body = new IllegalStateException("actual opaque filter body"), cleanup = new IllegalArgumentException("actual opaque filter cleanup");
			int[] closes = { 0 };
			NativeBooleanFilter callback = new NativeBooleanFilter() {
				@Override public boolean accept(RowState row) { if (bodyFailure) throw body; return true; }
				@Override public void close() { closes[0]++; throw cleanup; }
			};
			assertFalse(callback.capabilities().atPlacement(-1L).replaySafe(), "opaque callback is a negative capability boundary");
			Map<BorrowedFactorBatch.Source, BorrowedSourceView> witnesses = new IdentityHashMap<>();
			SlotPlan plan = new FilterPlan(new ExtensionPlan(fixture.leaf(), new CopyBinding[] { CopyBinding.slot(3, fixture.copySlot) }), callback, -1L);
			try (LmdbNativeFactorCursor input = LmdbNativeFactorAlgebra.open(plan, fixture.row);
					NativeFactorProjections consumer = new LmdbNativeFactorProjections(input, fixture.row,
							new int[][] { { 0, 1, 2, 3 } }, new boolean[] { true })) {
				if (bodyFailure) {
					assertSame(body, assertThrows(IllegalStateException.class, consumer::nextBatch));
					assertArrayEquals(new Throwable[] { cleanup }, body.getSuppressed());
					assertEquals(0, cleanup.getSuppressed().length);
				} else {
					assertTrue(consumer.nextBatch()); assertTrue(consumer.next(0));
					assertSame(cleanup, assertThrows(IllegalArgumentException.class, consumer::close));
					assertEquals(0, cleanup.getSuppressed().length);
				}
				captureRuntimeSources(fixture.runtime, witnesses); assertFalse(witnesses.isEmpty());
				stillLive(witnesses); assertEquals(0L, fixture.row.boundMask()); assertEquals(1, closes[0]);
			}
			assertEquals(1, closes[0]); stillLive(witnesses); fixture.retireRuntime(witnesses);
			reporter.publishEntry("boundary", "actual opaque callback semantic fallback/cleanup negative; physical readers have no injected close failure; row-tier exact primary and acyclic suppression");
		}
	}

