	/** One actual selected plan/source; instrumentation changes only physical Reader.close observation. */
	private static final class ChunkCloseOwner implements AutoCloseable {
		final OwnedFixture fixture;
		final RowState row;
		final LmdbNativePackedFtree.Runtime runtime;
		final List<ObservedPhysicalSource> sources = new ArrayList<>();
		final List<Byte> kinds = new ArrayList<>();
		final java.util.OptionalLong epoch;
		boolean armed;
		int callbacks, exports, opens, closes, callbackCloseCalls;
		boolean callbackSourceOpen;
		String phase = "unarmed", callbackPhase = "none", callbackSource = "none";
		ChunkCloseOwner(OwnedFixture fixture) throws Exception {
			this.fixture = fixture;
			assertFalse(fixture.runtime.chunksStarted, "SETUP_PREMISE: discard only the fixture's unused Runtime, never an evaluated plan");
			fixture.runtime.close();
			epoch = fixture.dataset.getSnapshotEpoch();
			assertTrue(epoch.isPresent(), "SETUP_PREMISE: actual LMDB snapshot epoch is present");
			NativeLmdbQuerySource source = mock(NativeLmdbQuerySource.class, delegatesTo(fixture.source));
			doAnswer(invocation -> {
				NativeLmdbQuerySource.NativeProbe real = fixture.source.newProbe();
				try { return probe(real); }
				catch (Exception | Error failure) { closeInstrumentationFailure(real, failure); throw failure; }
			}).when(source).newProbe();
			assertSame(fixture.source.idSpace(), source.idSpace()); assertEquals(fixture.source.hasCanonicalIds(), source.hasCanonicalIds());
			row = new RowState(source, fixture.row.layout, EmptyBindingSet.getInstance());
			assertTrue(NativeRowSeeder.seed(row.slots, row.layout, EmptyBindingSet.getInstance(), source));
			LmdbNativePackedFtree.Runtime opened = null;
			try {
				opened = LmdbNativePackedFtree.Runtime.open(fixture.plan, row);
				assertNotNull(opened, "SETUP_PREMISE: existing real selected plan admits the delegated actual source");
				assertSame(fixture.plan, opened.plan, "no replacement selector or second plan is introduced");
				runtime = opened;
			} catch (Exception | Error failure) {
				if (opened != null) closeInstrumentationFailure(opened, failure);
				closeInstrumentationFailure(row::closeDecodedInputs, failure); throw failure;
			}
		}
		LmdbNativePackedFtree.ChunkProjectionCursor cursor(int[][] outputs) {
			boolean[] exact = new boolean[outputs.length]; java.util.Arrays.fill(exact, true);
			return new LmdbNativePackedFtree.ChunkProjectionCursor(fixture.plan, row, runtime, outputs, exact);
		}
		void arm(String phase) { assertFalse(armed); assertEquals(0, callbacks); this.phase = phase; armed = true; }
		void assertPhysicalAdmission(LmdbNativePackedFtree.ChunkProjectionCursor cursor) {
			assertTrue(cursor.windowsEnabled, "SETUP_PREMISE: no test disables physical windows");
			assertTrue(exports > 0, "SETUP_PREMISE: actual key/bound cursor exports must be observed");
			assertTrue(sources.size() >= 2, "SETUP_PREMISE: real independent physical leaf Sources, not assigned descriptors");
			for (LmdbNativePackedFtree.NodePlan node : fixture.plan.nodes)
				if (node.slot == 1 || node.slot == 2)
					assertNotNull(cursor.chunk.data[node.ordinal].borrowed, "SETUP_PREMISE: actual selected leaf descriptor at slot " + node.slot);
			for (ObservedPhysicalSource source : sources) source.assertLive();
		}
		void assertClosed() {
			assertTrue(runtime.closed); assertEquals(opens, closes, "every actual delegate Reader closes once; " + receipt());
			assertTrue(opens > 0, "SETUP_PREMISE: physical Readers were actually opened");
			for (ObservedPhysicalSource source : sources) {
				assertEquals(1, source.releases); assertThrows(IllegalStateException.class, source.actual::checkOpen);
			}
			assertEquals(epoch, fixture.dataset.getSnapshotEpoch(), "original snapshot owner remains live after Runtime close");
			assertEquals(0L, row.boundMask());
		}
		String receipt() { return "phase=" + phase + "; callbackPhase=" + callbackPhase + "; callbackSource=" + callbackSource
				+ "; callbacks=" + callbacks + "; exports=" + exports + "; kinds=" + kinds + "; actualReaderOpenClose=" + opens + "/" + closes
				+ "; sourceOpenAtCallback=" + callbackSourceOpen + "; closeCallsAtCallback=" + callbackCloseCalls
				+ "; epoch=" + epoch + "; token=" + row.cancellation.isCancellationRequested() + "; runtimeClosed=" + runtime.closed; }
		NativeLmdbQuerySource.NativeProbe probe(NativeLmdbQuerySource.NativeProbe actual) throws java.io.IOException {
			var result = mock(NativeLmdbQuerySource.NativeProbe.class, delegatesTo(actual));
			Map<NativeLmdbQuerySource.NativeAdjacency, PhysicalBridge> bridges = new IdentityHashMap<>();
			doAnswer(i -> adjacency(actual.adjacency(i.getArgument(0), i.getArgument(1)), bridges)).when(result).adjacency(anyLong(), anyBoolean());
			doAnswer(i -> adjacency(actual.adjacency(i.getArgument(0), i.getArgument(1), i.getArgument(2)), bridges)).when(result).adjacency(anyLong(), anyBoolean(), any());
			return result;
		}
		NativeLmdbQuerySource.NativeAdjacency adjacency(NativeLmdbQuerySource.NativeAdjacency actual,
				Map<NativeLmdbQuerySource.NativeAdjacency, PhysicalBridge> bridges) {
			if (actual == null) return null;
			return bridges.computeIfAbsent(actual, key -> new PhysicalBridge(key, this)).view;
		}
		@Override public void close() { assertAll(runtime::close, row::closeDecodedInputs); }
	}

	@FunctionalInterface private interface PhysicalExport { boolean into(BorrowedFactorBatch target); }
	private static final class PhysicalBridge {
		final NativeLmdbQuerySource.NativeAdjacency actual, view;
		final ChunkCloseOwner owner;
		ObservedPhysicalSource source;
		BorrowedFactorBatch staging;
		ObservedPhysicalSource stagingOwner;
		PhysicalBridge(NativeLmdbQuerySource.NativeAdjacency actual, ChunkCloseOwner owner) {
			this.actual = actual; this.owner = owner;
			view = mock(NativeLmdbQuerySource.NativeAdjacency.class, delegatesTo(actual));
			doAnswer(i -> {
				assertNull(source, "SETUP_PREMISE: one retained factor Source per actual Runtime adjacency");
				BorrowedFactorBatch.Source retained = actual.openFactorSource();
				if (retained == null) return null;
				try {
					source = new ObservedPhysicalSource(retained, owner);
					owner.sources.add(source); return source;
				} catch (RuntimeException | Error failure) { closeInstrumentationFailure(retained, failure); throw failure; }
			}).when(view).openFactorSource();
			doAnswer(i -> export(i.getArgument(1), i.getArgument(2), target -> actual.borrowRun(i.getArgument(0), target, 0)))
					.when(view).borrowRun(anyLong(), any(BorrowedFactorBatch.class), anyInt());
			doAnswer(i -> {
				var real = actual.openBoundRunCursor();
				if (real == null) return null;
				var cursor = mock(NativeLmdbQuerySource.NativeAdjacency.BoundRunCursor.class, delegatesTo(real));
				doAnswer(b -> export(b.getArgument(0), b.getArgument(1), target -> real.borrow(target, 0)))
						.when(cursor).borrow(any(BorrowedFactorBatch.class), anyInt());
				return cursor;
			}).when(view).openBoundRunCursor();
			doAnswer(i -> {
				var real = actual.openKeyRunCursor();
				if (real == null) return null;
				var cursor = mock(NativeLmdbQuerySource.NativeAdjacency.KeyRunCursor.class, delegatesTo(real));
				doAnswer(b -> export(b.getArgument(0), b.getArgument(1), target -> real.borrow(target, 0)))
						.when(cursor).borrow(any(BorrowedFactorBatch.class), anyInt());
				return cursor;
			}).when(view).openKeyRunCursor();
		}
		boolean export(BorrowedFactorBatch target, int lane, PhysicalExport operation) {
			ObservedPhysicalSource delivered = assertInstanceOf(ObservedPhysicalSource.class, target.source(),
					"SETUP_PREMISE: Runtime export target is one of this actual owner's retained physical Sources");
			assertSame(owner, delivered.owner);
			if (stagingOwner != delivered) {
				staging = new BorrowedFactorBatch(delivered.actual, 1); stagingOwner = delivered;
			}
			staging.reset(1);
			if (!operation.into(staging)) return false;
			copyPhysicalDescriptor(target, lane, staging, 0); owner.exports++; owner.kinds.add(staging.kind(0)); return true;
		}
	}
	private static final class ObservedPhysicalSource extends BorrowedFactorBatch.Source {
		final BorrowedFactorBatch.Source actual;
		final ChunkCloseOwner owner;
		final BorrowedSourceView witness;
		int releases;
		ObservedPhysicalSource(BorrowedFactorBatch.Source actual, ChunkCloseOwner owner) {
			super(owner.fixture.dataset, true); this.actual = actual; this.owner = owner;
			witness = NativeQuerySourceAccess.borrowedSourceView(actual);
			assertTrue(witness.exact(), "SETUP_PREMISE: real direct physical Source must be exact");
			if (!owner.sources.isEmpty()) {
				BorrowedSourceView first = owner.sources.getFirst().witness;
				assertSame(first.identity(), witness.identity(), "SETUP_PREMISE: wrappers share one actual physical view");
				assertEquals(first.lifetime(), witness.lifetime()); assertEquals(first.snapshot(), witness.snapshot());
			}
		}
		void assertLive() { actual.checkOpen(); assertEquals(witness, NativeQuerySourceAccess.borrowedSourceView(actual)); }
		@Override protected void validate() { actual.checkOpen(); }
		@Override protected void release() { releases++; actual.close(); }
		@Override public BorrowedFactorBatch.Reader openReader() {
			checkOpen(); BorrowedFactorBatch shadow = new BorrowedFactorBatch(actual, 1);
			BorrowedFactorBatch.Reader delegate = actual.openReader(); owner.opens++;
			return new BorrowedFactorBatch.Reader() {
				boolean closed;
				@Override public void bind(BorrowedFactorBatch batch, int lane) {
					assertSame(ObservedPhysicalSource.this, batch.source()); shadow.reset(1);
					copyPhysicalDescriptor(shadow, 0, batch, lane); delegate.bind(shadow, 0);
				}
				@Override public int copyFibers(long offset, int maximum, long[] values, long[] weights) {
					return delegate.copyFibers(offset, maximum, values, weights);
				}
				@Override public void close() {
					if (closed) return; closed = true;
					try { delegate.close(); } finally { owner.closes++; }
					if (owner.armed && owner.callbacks == 0) {
						assertLive(); owner.callbacks++; owner.callbackPhase = owner.phase; owner.callbackSource = witness.toString();
						owner.callbackSourceOpen = true; owner.callbackCloseCalls = owner.closes;
						owner.row.cancellation.requestCancellation();
					}
				}
			};
		}
	}
	private static void closeInstrumentationFailure(AutoCloseable resource, Throwable failure) {
		try { resource.close(); }
		catch (Throwable closing) { if (closing != failure) failure.addSuppressed(closing); }
	}
	private static void copyPhysicalDescriptor(BorrowedFactorBatch target, int lane, BorrowedFactorBatch from, int fromLane) {
		byte kind = from.kind(fromLane); long count = from.count(fromLane);
		assertTrue(count > 0L, "SETUP_PREMISE: actual successful physical export has a positive count");
		if (kind == BorrowedFactorBatch.HEAP) target.bindHeap(lane, from.array(fromLane), from.coordinate(fromLane), Math.toIntExact(count));
		else {
			assertTrue(kind == BorrowedFactorBatch.CSF_PAGE || kind == BorrowedFactorBatch.ENCODED_RUN || kind == BorrowedFactorBatch.RAW_U64,
					"SETUP_PREMISE: only exact actual physical descriptors are delegated, never selected/dependent views");
			target.bindNative(lane, kind, from.address(fromLane), from.reference(fromLane), from.coordinate(fromLane), count);
		}
	}

	@ParameterizedTest(name = "cleanupFaults={0}")
	@ValueSource(booleans = { false, true })
	void actualRuntimeAttemptsEveryNativeCloseAndKeepsFirstFailure(boolean cleanupFaults) throws Exception {
		try (OwnedFixture fixture = new OwnedFixture(directory, 4, false);
				RuntimeFailureOwner owner = new RuntimeFailureOwner(fixture)) {
			assertEquals(16L, fixture.expected.values().stream().mapToLong(Long::longValue).sum(), "independent Memory fixture is the existing real two-sibling relation");
			assertTrue(owner.runtime.roots instanceof LmdbNativePackedFtree.KeyRootProducer, "SETUP_PREMISE: naturally selected actual native key cursor owns the root close");
			LmdbNativePackedFtree.EdgeRuntime selected = null;
			for (var edge : owner.runtime.primaryEdges) if (edge != null) { selected = edge; break; }
			assertNotNull(selected, "SETUP_PREMISE: real selected Runtime has an actual EdgeRuntime");
			BorrowedFactorBatch.Source source = selected.factorSource();
			assertInstanceOf(RuntimeFailureSource.class, source, "SETUP_PREMISE: actual Edge factory returned the delegating retained physical source");
			assertEquals(1, owner.sources.size(), "exactly the selected Edge's real factor Source is acquired; no descriptor or extra traversal");
			owner.sources.getFirst().assertLive();
			assertEquals(1, owner.probeOpens, "SETUP_PREMISE: this Runtime actually opened exactly one delegated primary/lookup probe before close");
			assertEquals(0, owner.opens, "this cleanup-owner qualification consumes no Reader or descriptor");
			owner.faultsArmed = cleanupFaults;
			Throwable observed = null;
			try { owner.runtime.close(); }
			catch (RuntimeException | Error failure) { observed = failure; }
			finally { owner.faultsArmed = false; }
			owner.writeReceipt(cleanupFaults, observed);
			assertTrue(owner.runtime.closed);
			assertEquals(1, owner.probeCloses, "actual probe.close completed before any injected later exception");
			assertEquals(owner.probeOpens, owner.probeCloses, "every actual opened probe settled before its injected close failure");
			assertEquals(owner.boundOpens, owner.boundCloses, "every actual Edge cursor close attempted/completed");
			assertTrue(owner.boundOpens >= 2, "SETUP_PREMISE: actual selected sibling cursors were opened");
			assertEquals(1, owner.keyOpens); assertEquals(1, owner.keyCloses);
			assertEquals(1, owner.sources.getFirst().releases);
			assertThrows(IllegalStateException.class, owner.sources.getFirst().actual::checkOpen);
			assertEquals(owner.epoch, fixture.dataset.getSnapshotEpoch(), "outer dataset still owns the real snapshot after all runtime native releases");
			assertEquals(0L, owner.row.boundMask());
			assertFalse(owner.row.cancellation.isCancellationRequested(), "ordinary multi-cleanup contract; no universal cancellation policy is inferred");
			assertTrue(owner.events.indexOf("edge-source-settled") < owner.events.indexOf("probe-settled"));
			owner.runtime.close();
			assertEquals(1, owner.probeCloses); assertEquals(1, owner.sources.getFirst().releases);
			if (cleanupFaults) {
				assertSame(owner.sourceFailure, observed, "first actual Edge Source cleanup failure must not disappear behind the later actual probe close");
				assertArrayEquals(new Throwable[] { owner.probeFailure }, observed.getSuppressed(), "later actual cleanup identity is retained exactly once");
				assertEquals(0, owner.probeFailure.getSuppressed().length, "no suppression cycle back to the primary");
			} else assertNull(observed, "unarmed genuine native close owner remains clean");
		}
	}

