	/** Independent cleanup diagnostic; no root export/Chunk callback production change is involved. */
	private static final class RuntimeFailureOwner implements AutoCloseable {
		final OwnedFixture fixture;
		final RowState row;
		final LmdbNativePackedFtree.Runtime runtime;
		final List<RuntimeFailureSource> sources = new ArrayList<>();
		final List<Byte> kinds = new ArrayList<>();
		final List<String> events = new ArrayList<>();
		final java.util.OptionalLong epoch;
		final IllegalStateException sourceFailure = new IllegalStateException("actual-edge-source-close-after-settlement");
		final IllegalStateException probeFailure = new IllegalStateException("actual-probe-close-after-settlement");
		boolean faultsArmed;
		boolean edgeFaultsArmed;
		int edgeBoundFaults, edgeSourceFaults;
		final IllegalStateException boundFailure = new IllegalStateException("actual-bound-cursor-close-after-settlement");
		int probeOpens, probeCloses, boundOpens, boundCloses, keyOpens, keyCloses, exports, opens, closes;
		RuntimeFailureOwner(OwnedFixture fixture) throws Exception {
			this.fixture = fixture;
			assertFalse(fixture.runtime.chunksStarted, "SETUP_PREMISE: retire only the existing fixture's unused Runtime");
			fixture.runtime.close();
			epoch = fixture.dataset.getSnapshotEpoch(); assertTrue(epoch.isPresent());
			NativeLmdbQuerySource source = org.mockito.Mockito.mock(NativeLmdbQuerySource.class, org.mockito.AdditionalAnswers.delegatesTo(fixture.source));
			org.mockito.Mockito.doAnswer(i -> {
				var actual = fixture.source.newProbe();
				probeOpens++; events.add("probe-opened");
				try { return probe(actual); }
				catch (Exception | Error failure) { runtimeCloseInstrumentationFailure(actual, failure); throw failure; }
			}).when(source).newProbe();
			assertSame(fixture.source.idSpace(), source.idSpace());
			assertEquals(fixture.source.hasCanonicalIds(), source.hasCanonicalIds());
			row = new RowState(source, fixture.row.layout, EmptyBindingSet.getInstance());
			assertTrue(NativeRowSeeder.seed(row.slots, row.layout, EmptyBindingSet.getInstance(), source));
			LmdbNativePackedFtree.Runtime opened = null;
			try {
				opened = LmdbNativePackedFtree.Runtime.open(fixture.plan, row);
				assertNotNull(opened); assertSame(fixture.plan, opened.plan, "one actual selected plan, no second Planner/selector");
				runtime = opened;
			} catch (Exception | Error failure) {
				if (opened != null) runtimeCloseInstrumentationFailure(opened, failure);
				runtimeCloseInstrumentationFailure(row::closeDecodedInputs, failure); throw failure;
			}
		}
		NativeLmdbQuerySource.NativeProbe probe(NativeLmdbQuerySource.NativeProbe actual) throws java.io.IOException {
			var result = org.mockito.Mockito.mock(NativeLmdbQuerySource.NativeProbe.class, org.mockito.AdditionalAnswers.delegatesTo(actual));
			Map<NativeLmdbQuerySource.NativeAdjacency, RuntimeFailureBridge> bridges = new IdentityHashMap<>();
			org.mockito.Mockito.doAnswer(i -> actualAdjacency(actual.adjacency(i.getArgument(0), i.getArgument(1)), bridges))
					.when(result).adjacency(org.mockito.ArgumentMatchers.anyLong(), org.mockito.ArgumentMatchers.anyBoolean());
			org.mockito.Mockito.doAnswer(i -> actualAdjacency(actual.adjacency(i.getArgument(0), i.getArgument(1), i.getArgument(2)), bridges))
					.when(result).adjacency(org.mockito.ArgumentMatchers.anyLong(), org.mockito.ArgumentMatchers.anyBoolean(), org.mockito.ArgumentMatchers.any());
			org.mockito.Mockito.doAnswer(i -> {
				actual.close(); probeCloses++; events.add("probe-settled");
				if (faultsArmed) throw probeFailure;
				return null;
			}).when(result).close();
			return result;
		}
		NativeLmdbQuerySource.NativeAdjacency actualAdjacency(NativeLmdbQuerySource.NativeAdjacency actual,
				Map<NativeLmdbQuerySource.NativeAdjacency, RuntimeFailureBridge> bridges) {
			return actual == null ? null : bridges.computeIfAbsent(actual, key -> new RuntimeFailureBridge(key, this)).view;
		}
		void writeReceipt(boolean armed, Throwable observed) throws java.io.IOException {
			var witness = sources.getFirst().witness;
			String text = "field\tvalue\ncase\t" + armed + "\nactualRoot\t" + runtime.roots.getClass().getName()
					+ "\nactualSource\t" + sources.getFirst().actual.getClass().getName() + "\nviewIdentity\t" + witness.identity()
					+ "\nviewLifetime\t" + witness.lifetime() + "\nviewSnapshotRevision\t" + witness.snapshot() + "\nphysicalDatasetEpoch\t" + epoch
					+ "\nactualReaderOpenClose\t" + opens + "/" + closes + "\nactualBoundCursorOpenClose\t" + boundOpens + "/" + boundCloses
					+ "\nactualRootCursorOpenClose\t" + keyOpens + "/" + keyCloses + "\nprobeOpens\t" + probeOpens + "\nprobeCloses\t" + probeCloses
					+ "\nsourceReleases\t" + sources.getFirst().releases + "\nevents\t" + events
					+ "\nprimaryIsSourceFailure\t" + (observed == sourceFailure) + "\nprimaryIsProbeFailure\t" + (observed == probeFailure)
					+ "\nprimaryType\t" + (observed == null ? "none" : observed.getClass().getName()) + "\n";
			System.out.println("RDF4J_RUNTIME_MULTI_CLOSE_V1\t" + text.replace("\t", "\\t").replace("\n", "\\n"));
		}
		void writeEdgeReceipt(Throwable observed) {
			var witness = sources.getFirst().witness;
			String text = "case=bound-cursor-plus-source; actualRoot=" + runtime.roots.getClass().getName()
					+ "; actualSource=" + sources.getFirst().actual.getClass().getName() + "; viewIdentity=" + witness.identity()
					+ "; viewLifetime=" + witness.lifetime() + "; viewSnapshotRevision=" + witness.snapshot() + "; physicalDatasetEpoch=" + epoch
					+ "; actualReaders=" + opens + "/" + closes + "; actualBoundCursors=" + boundOpens + "/" + boundCloses
					+ "; actualRootCursors=" + keyOpens + "/" + keyCloses + "; actualProbes=" + probeOpens + "/" + probeCloses
					+ "; sourceReleases=" + sources.getFirst().releases + "; edgeBoundFaults=" + edgeBoundFaults + "; edgeSourceFaults=" + edgeSourceFaults
					+ "; sourceProbeArm=" + faultsArmed + "; events=" + events + "; primaryIsBoundFailure=" + (observed == boundFailure)
					+ "; primaryIsSourceFailure=" + (observed == sourceFailure) + "; primaryIsProbeFailure=" + (observed == probeFailure)
					+ "; primaryType=" + (observed == null ? "none" : observed.getClass().getName());
			System.out.println("RDF4J_EDGE_MULTI_CLOSE_V1\t" + text);
		}
		@Override public void close() { assertAll(runtime::close, row::closeDecodedInputs); }
	}

	@FunctionalInterface private interface RuntimeFailureExport { boolean into(BorrowedFactorBatch target); }
	private static final class RuntimeFailureBridge {
		final NativeLmdbQuerySource.NativeAdjacency actual, view;
		final RuntimeFailureOwner owner;
		RuntimeFailureSource source;
		BorrowedFactorBatch staging;
		RuntimeFailureSource stagingOwner;
		RuntimeFailureBridge(NativeLmdbQuerySource.NativeAdjacency actual, RuntimeFailureOwner owner) {
			this.actual = actual; this.owner = owner;
			view = org.mockito.Mockito.mock(NativeLmdbQuerySource.NativeAdjacency.class, org.mockito.AdditionalAnswers.delegatesTo(actual));
			org.mockito.Mockito.doAnswer(i -> {
				assertNull(source, "SETUP_PREMISE: one retained factor Source per actual Runtime adjacency");
				BorrowedFactorBatch.Source retained = actual.openFactorSource();
				if (retained == null) return null;
				try {
					source = new RuntimeFailureSource(retained, owner);
					owner.sources.add(source); return source;
				} catch (RuntimeException | Error failure) { runtimeCloseInstrumentationFailure(retained, failure); throw failure; }
			}).when(view).openFactorSource();
			org.mockito.Mockito.doAnswer(i -> export(i.getArgument(1), i.getArgument(2), target -> actual.borrowRun(i.getArgument(0), target, 0)))
					.when(view).borrowRun(org.mockito.ArgumentMatchers.anyLong(), org.mockito.ArgumentMatchers.any(BorrowedFactorBatch.class), org.mockito.ArgumentMatchers.anyInt());
			org.mockito.Mockito.doAnswer(i -> {
				var real = actual.openBoundRunCursor();
				if (real == null) return null;
				var cursor = org.mockito.Mockito.mock(NativeLmdbQuerySource.NativeAdjacency.BoundRunCursor.class, org.mockito.AdditionalAnswers.delegatesTo(real));
				owner.boundOpens++;
				org.mockito.Mockito.doAnswer(c -> {
					real.close(); owner.boundCloses++; owner.events.add("bound-cursor-settled");
					if (owner.edgeFaultsArmed && source != null) {
						owner.edgeBoundFaults++; owner.events.add("bound-cursor-fault"); throw owner.boundFailure;
					}
					return null;
				}).when(cursor).close();
				org.mockito.Mockito.doAnswer(b -> export(b.getArgument(0), b.getArgument(1), target -> real.borrow(target, 0)))
						.when(cursor).borrow(org.mockito.ArgumentMatchers.any(BorrowedFactorBatch.class), org.mockito.ArgumentMatchers.anyInt());
				return cursor;
			}).when(view).openBoundRunCursor();
			org.mockito.Mockito.doAnswer(i -> {
				var real = actual.openKeyRunCursor();
				if (real == null) return null;
				var cursor = org.mockito.Mockito.mock(NativeLmdbQuerySource.NativeAdjacency.KeyRunCursor.class, org.mockito.AdditionalAnswers.delegatesTo(real));
				owner.keyOpens++;
				org.mockito.Mockito.doAnswer(c -> { real.close(); owner.keyCloses++; owner.events.add("key-cursor-settled"); return null; }).when(cursor).close();
				org.mockito.Mockito.doAnswer(b -> export(b.getArgument(0), b.getArgument(1), target -> real.borrow(target, 0)))
						.when(cursor).borrow(org.mockito.ArgumentMatchers.any(BorrowedFactorBatch.class), org.mockito.ArgumentMatchers.anyInt());
				return cursor;
			}).when(view).openKeyRunCursor();
		}
		boolean export(BorrowedFactorBatch target, int lane, RuntimeFailureExport operation) {
			RuntimeFailureSource delivered = assertInstanceOf(RuntimeFailureSource.class, target.source(),
					"SETUP_PREMISE: Runtime export target is one of this actual owner's retained physical Sources");
			assertSame(owner, delivered.owner);
			if (stagingOwner != delivered) {
				staging = new BorrowedFactorBatch(delivered.actual, 1); stagingOwner = delivered;
			}
			staging.reset(1);
			if (!operation.into(staging)) return false;
			runtimeCloseCopyPhysicalDescriptor(target, lane, staging, 0); owner.exports++; owner.kinds.add(staging.kind(0)); return true;
		}
	}
	private static final class RuntimeFailureSource extends BorrowedFactorBatch.Source {
		final BorrowedFactorBatch.Source actual;
		final RuntimeFailureOwner owner;
		final BorrowedSourceView witness;
		int releases;
		RuntimeFailureSource(BorrowedFactorBatch.Source actual, RuntimeFailureOwner owner) {
			super(owner.fixture.dataset, true); this.actual = actual; this.owner = owner;
			witness = NativeQuerySourceAccess.borrowedSourceView(actual);
			assertTrue(witness.exact(), "SETUP_PREMISE: real direct physical Source must be exact");
			if (!owner.sources.isEmpty()) {
				BorrowedSourceView first = owner.sources.getFirst().witness;
				assertSame(first.identity(), witness.identity(), "SETUP_PREMISE: wrappers share one actual physical view");
				assertEquals(first.lifetime(), witness.lifetime()); assertEquals(first.snapshot(), witness.snapshot());
			}
		}
		void assertLive() { actual.checkOpen(); assertEquals(witness, NativeQuerySourceAccess.borrowedSourceView(actual)); }
		@Override protected void validate() { actual.checkOpen(); }
		@Override protected void release() {
			releases++; actual.close();
			assertThrows(IllegalStateException.class, actual::checkOpen, "actual physical Source settles before the injected failure");
			owner.events.add("edge-source-settled");
			if (owner.edgeFaultsArmed) { owner.edgeSourceFaults++; owner.events.add("edge-source-fault"); }
			if (owner.faultsArmed || owner.edgeFaultsArmed) throw owner.sourceFailure;
		}
		@Override public BorrowedFactorBatch.Reader openReader() {
			checkOpen(); BorrowedFactorBatch shadow = new BorrowedFactorBatch(actual, 1);
			BorrowedFactorBatch.Reader delegate = actual.openReader(); owner.opens++;
			return new BorrowedFactorBatch.Reader() {
				boolean closed;
				@Override public void bind(BorrowedFactorBatch batch, int lane) {
					assertSame(RuntimeFailureSource.this, batch.source()); shadow.reset(1);
					runtimeCloseCopyPhysicalDescriptor(shadow, 0, batch, lane); delegate.bind(shadow, 0);
				}
				@Override public int copyFibers(long offset, int maximum, long[] values, long[] weights) {
					return delegate.copyFibers(offset, maximum, values, weights);
				}
				@Override public void close() {
					if (closed) return; closed = true;
					try { delegate.close(); } finally { owner.closes++; }

				}
			};
		}
	}
	private static void runtimeCloseInstrumentationFailure(AutoCloseable resource, Throwable failure) {
		try { resource.close(); }
		catch (Throwable closing) { if (closing != failure) failure.addSuppressed(closing); }
	}
	private static void runtimeCloseCopyPhysicalDescriptor(BorrowedFactorBatch target, int lane, BorrowedFactorBatch from, int fromLane) {
		byte kind = from.kind(fromLane); long count = from.count(fromLane);
		assertTrue(count > 0L, "SETUP_PREMISE: actual successful physical export has a positive count");
		if (kind == BorrowedFactorBatch.HEAP) target.bindHeap(lane, from.array(fromLane), from.coordinate(fromLane), Math.toIntExact(count));
		else {
			assertTrue(kind == BorrowedFactorBatch.CSF_PAGE || kind == BorrowedFactorBatch.ENCODED_RUN || kind == BorrowedFactorBatch.RAW_U64,
					"SETUP_PREMISE: only exact actual physical descriptors are delegated, never selected/dependent views");
			target.bindNative(lane, kind, from.address(fromLane), from.reference(fromLane), from.coordinate(fromLane), count);
		}
	}


	private static BorrowedFactorBatch copyPhysical(BorrowedFactorBatch from, int lane) {
		BorrowedFactorBatch copy = new BorrowedFactorBatch(from.source(), 1); copy.reset(1); copy.copyLaneFrom(0, from, lane); return copy;
	}
	private static java.util.Set<Value> decodedValues(BorrowedFactorBatch.Cursor reader, NativeLmdbQuerySource source) {
		java.util.Set<Value> values = new java.util.HashSet<>(); long weight = 0;
		while (reader.next()) { values.add(source.lazyValue(reader.value(), ValuePosition.OBJECT)); weight += reader.weight(); }
		assertEquals(2L, weight); assertEquals(2, values.size()); return values;
	}
