	private static PatternPlan pattern(long predicate, int object) {
		return new PatternPlan(Term.slot(0), Term.constant(predicate), Term.slot(object), Term.unbound(),
				ContextConstraint.UNRESTRICTED, false, Double.NaN);
	}
	private static void capture(FactorEnvironment factors, Map<BorrowedFactorBatch.Source, BorrowedSourceView> witnesses) {
		for (long mask = factors.groupLeaders(); mask != 0L; mask &= mask - 1L) {
			int slot = Long.numberOfTrailingZeros(mask); assertFalse(factors.isTuple(slot));
			BorrowedFactorBatch.Source source = factors.batch(slot).source();
			BorrowedSourceView actual = NativeQuerySourceAccess.borrowedSourceView(source);
			BorrowedSourceView previous = witnesses.putIfAbsent(source, actual);
			if (previous != null) { assertSame(previous.identity(), actual.identity()); assertEquals(previous, actual); }
			assertTrue(actual.exact());
		}
	}
	private static void captureRuntimeSources(LmdbNativePackedFtree.Runtime runtime,
			Map<BorrowedFactorBatch.Source, BorrowedSourceView> witnesses) {
		for (LmdbNativePackedFtree.EdgeRuntime edge : runtime.primaryEdges)
			if (edge != null && edge.borrowedSource != null)
				witnesses.putIfAbsent(edge.borrowedSource, NativeQuerySourceAccess.borrowedSourceView(edge.borrowedSource));
	}
	private static void stillLive(Map<BorrowedFactorBatch.Source, BorrowedSourceView> witnesses) {
		witnesses.forEach((source, previous) -> {
			source.checkOpen(); BorrowedSourceView actual = NativeQuerySourceAccess.borrowedSourceView(source);
			assertSame(previous.identity(), actual.identity()); assertEquals(previous, actual);
		});
	}
	private static Map<List<Value>, Long> memoryBag(SailRepository memory) {
		Map<List<Value>, Long> result = new HashMap<>();
		try (var connection = memory.getConnection()) {
			var query = connection.prepareTupleQuery(QUERY); query.setIncludeInferred(false);
			try (var rows = query.evaluate()) {
				while (rows.hasNext()) { BindingSet row = rows.next(); result.merge(List.of(row.getValue("s"), row.getValue("o"), row.getValue("t")), 1L, Math::addExact); }
			}
		}
		return result;
	}
	private static IRI iri(String local) { return VF.createIRI(EX + local); }
